export const LANGS = ['uz', 'ru', 'en', 'kk', 'ky', 'tg', 'tk', 'az', 'prs', 'ps'];

export const DICT = {};
for (const line of RAW.split('\n')) {
  if (!line.trim()) continue;
  const parts = line.split('|');
  const key = parts.shift();
  DICT[key] = Object.fromEntries(LANGS.map((l, i) => [l, parts[i]]));
}
